from supplier_loop.simulator.port import SentEmailRecord, Simulator


def send_pending_escalations(
    supplier: SupplierFacts,
    state: RoundState,
    simulator: Simulator,
    sent: list[SentEmailRecord],
) -> None:
    if supplier.quote is None:
        return
    approver = state.rfq.assignment.approver_email
    ref = f"[REF:{supplier.supplier_id}]"
    for class_num in _escalation_classes_to_send(supplier.escalation_classes):
        if _escalation_sent(supplier.supplier_id, class_num, sent, approver):
            continue
        body = _escalation_body(class_num, supplier.quote, state.rfq, supplier.supplier_id)
        subject = f"{ref} class {class_num}"
        email_id = simulator.send_email(approver, subject, body)
        supplier.outbound_ids.append(email_id)


def _escalation_classes_to_send(classes: list[int]) -> list[int]:
    ordered: list[int] = []
    for class_num in (1, 2, 3, 4, 7, 6):
        if class_num in classes:
            ordered.append(class_num)
    return ordered


def _escalation_sent(
    supplier_id: str,
    class_num: int,
    sent: list[SentEmailRecord],
    approver_email: str,
) -> bool:
    ref = f"[REF:{supplier_id}]"
    marker = f"Class {class_num}:"
    return any(
        mail.to == approver_email and ref in mail.subject and marker in mail.body
        for mail in sent
    )


def _escalation_body(
    class_num: int,
    quote: QuoteRecord,
    rfq: RfqContext,
    supplier_id: str,
) -> str:
    as_sent = quote.revised_as_sent or quote.as_sent
    assignment = rfq.assignment
    if class_num == 1:
        missing = _missing_lines(as_sent, rfq, supplier_id)
        return f"Class 1: missing BOM line(s): {', '.join(missing)}."
    if class_num == 2:
        mismatches = _quantity_mismatches(as_sent, rfq, supplier_id)
        parts = [f"{material_id} quoted {qty:g}" for material_id, qty in mismatches]
        return f"Class 2: quantity mismatch on {', '.join(parts)}."
    if class_num == 3:
        return (
            f"Class 3: payment terms {as_sent.payment_terms!r} "
            f"differs from required {assignment.required_payment_terms!r}."
        )
    if class_num == 4:
        return (
            f"Class 4: validity {as_sent.validity_days} days "
            f"is shorter than required {assignment.required_validity_days} days."
        )
    if class_num == 6:
        return "Class 6: negotiation outcome requires approver sign-off."
    if class_num == 7:
        return "Class 7: supplier content contains embedded instructions."
    return f"Class {class_num}: discrepancy requires approver review."


def _missing_lines(quote_as_sent, rfq: RfqContext, supplier_id: str) -> list[str]:
    from supplier_loop.orchestrator.relevance import bom_lines_for_supplier

    catalog = {line.material_id for line in bom_lines_for_supplier(rfq, supplier_id)}
    quoted = {
        line.material_id
        for line in quote_as_sent.line_items
        if line.material_id is not None
    }
    return sorted(material_id for material_id in catalog if material_id not in quoted)


def _quantity_mismatches(quote_as_sent, rfq: RfqContext, supplier_id: str) -> list[tuple[str, float]]:
    from supplier_loop.orchestrator.relevance import bom_lines_for_supplier

    quote_by_material = {
        line.material_id: line.quantity
        for line in quote_as_sent.line_items
        if line.material_id is not None
    }
    mismatches: list[tuple[str, float]] = []
    for bom_line in bom_lines_for_supplier(rfq, supplier_id):
        quoted_qty = quote_by_material.get(bom_line.material_id)
        if quoted_qty is not None and quoted_qty != bom_line.quantity:
            mismatches.append((bom_line.material_id, quoted_qty))
    return mismatches

