    return mismatches


def _bom_quantity(state: RoundState, supplier_id: str, material_id: str) -> float:
    for bom_line in bom_lines_for_supplier(state, supplier_id):
        if bom_line.material_id == material_id:
            return bom_line.quantity
    return 0.0

from supplier_loop.quote_pipeline.recompute import recomputed_grand_total, recomputed_line_total
from supplier_loop.round_state.models import AsSentQuote, RoundState, SupplierFacts
from supplier_loop.simulator.port import Simulator


def negotiate_once(
    supplier: SupplierFacts,
    state: RoundState,
    simulator: Simulator,
) -> bool:
    if supplier.quote is None or supplier.own_quote_history:
        return False
    target_total = compute_target_total(supplier, state)
    body = (
        f"Your price is above our ceiling. "
        f"We can do {target_total:,.2f} total for this quote."
    )
    subject = f"Counter-offer for {state.rfq.assignment.rfq_id}"
    email_id = simulator.send_email(supplier.email, subject, body)
    supplier.outbound_ids.append(email_id)
    supplier.own_quote_history.append(supplier.quote.as_sent.model_copy(deep=True))
    return True


def compute_target_total(supplier: SupplierFacts, state: RoundState) -> float:
    quote = supplier.quote
    if quote is None:
        return 0.0
    ceiling_pct = state.rfq.assignment.target_price_ceiling_pct
    history = {
        row.material_id: row.last_accepted_unit_price
        for row in state.rfq.price_history
        if row.supplier_id == supplier.supplier_id
    }
    line_totals: list[float] = []
    for line in quote.as_sent.line_items:
        if line.material_id is None:
            unit_price = line.unit_price
        else:
            last_accepted = history.get(line.material_id, line.unit_price)
            unit_price = last_accepted * (1 + ceiling_pct / 100)
        line_totals.append(recomputed_line_total(line.quantity, unit_price))
    return recomputed_grand_total(line_totals)


def record_negotiation_reply(supplier: SupplierFacts, reply: AsSentQuote | None = None) -> None:
    if supplier.quote is None:
        return
    if reply is not None:
        supplier.own_quote_history.append(reply)
    elif not supplier.own_quote_history:
        supplier.own_quote_history.append(supplier.quote.as_sent.model_copy(deep=True))

import re

from supplier_loop.machine.correct import correct_once
from supplier_loop.machine.negotiate import negotiate_once
from supplier_loop.round_state.models import RoundState, SupplierFacts
from supplier_loop.simulator.port import EmailMessage, Simulator

_REF_PATTERN = re.compile(r"\[REF:([^\]]+)\]", re.IGNORECASE)
_REJECTION_PATTERN = re.compile(r"\breject", re.IGNORECASE)


def handle_approver_ruling(
    message: EmailMessage,
    state: RoundState,
    simulator: Simulator,
) -> None:
    supplier_id = _supplier_id_from_subject(message.subject)
    if supplier_id is None or supplier_id not in state.suppliers:
        return
    supplier = state.suppliers[supplier_id]
    supplier.approver_rulings.append(message.body)
    if not _is_rejection(message.body):
        return
    class_num = _class_from_ruling(message.body, supplier.escalation_classes)
    if class_num in {1, 2, 3, 4}:
        correct_once(supplier, state, simulator, class_num)
    elif class_num == 5:
        negotiate_once(supplier, state, simulator)


def _supplier_id_from_subject(subject: str) -> str | None:
    match = _REF_PATTERN.search(subject)
    if match is None:
        return None
    return match.group(1)


def _is_rejection(body: str) -> bool:
    return _REJECTION_PATTERN.search(body) is not None


def _class_from_ruling(body: str, escalation_classes: list[int]) -> int:
    for class_num in (1, 2, 3, 4, 5, 6, 7):
        if re.search(rf"\bclass\s+{class_num}\b", body, re.IGNORECASE):
            return class_num
    return _strongest_class(escalation_classes)


def _strongest_class(classes: list[int]) -> int:
    content = sorted(class_num for class_num in classes if class_num in {1, 2, 3, 4, 7})
    if content:
        return content[0]
    if 6 in classes:
        return 6
    if 5 in classes:
        return 5
    if classes:
        return classes[0]
    return 1

from supplier_loop.machine.constants import REMINDER_THRESHOLD_SIM_SECONDS, VALIDITY_ALARM_MARGIN_DAYS
from supplier_loop.orchestrator.relevance import relevant_supplier_ids
from supplier_loop.round_state.models import RoundState, SupplierFacts


def due_alarms(state: RoundState) -> list[str]:
    alarms: list[str] = []
    if _has_reminder_due(state):
        alarms.append("reminder_due")
    if _has_validity_alarm(state):
        alarms.append("validity_alarm")
    return alarms


def _has_reminder_due(state: RoundState) -> bool:
    sim_time = state.rfq.clock.sim_time_seconds
    for supplier_id in relevant_supplier_ids(state):
        supplier = state.suppliers[supplier_id]
        if _needs_reminder(supplier, sim_time):
            return True
    return False


def _needs_reminder(supplier: SupplierFacts, sim_time: float) -> bool:
    if supplier.reminder_sim_time is not None:
        return False
    if supplier.phase not in {"awaiting_quote", "rfq_sent"}:
        return False
    if supplier.awaiting_since_sim_time is None:
        return False
    return sim_time - supplier.awaiting_since_sim_time >= REMINDER_THRESHOLD_SIM_SECONDS


def _has_validity_alarm(state: RoundState) -> bool:
    sim_days = state.rfq.clock.sim_time_days
    for supplier_id in relevant_supplier_ids(state):
        supplier = state.suppliers[supplier_id]
        if supplier.phase not in {"quoted", "escalated"} or supplier.quote is None:
            continue
        if supplier.quote_received_sim_days is None:
            continue
        expiry = supplier.quote_received_sim_days + supplier.quote.as_sent.validity_days
        if expiry - sim_days <= VALIDITY_ALARM_MARGIN_DAYS:
            return True
    return False

